"""Fifty original, distinct lessons. References support methods, not validated protocols."""
def extend(D, add):
    before={s['code'] for s in D['skills']}
    def new(code,title,topic,goal,cue,setup,entries,deps=(),priority='Useful extra',maintenance=False):
        add(code,title,topic,goal,cue,setup,'A10; P11; P22; R01',entries,deps,priority)
        D['skills'][-1]['maintenance']=maintenance
    new('STAY','Stay until released','Foundations','Remain in a chosen comfortable position through a short pause or small handler movement.','Stay; free','A quiet enclosed room, non-slip floor and any comfortable position. Duration and distance grow separately.',[
      ('Stay through a small pause','Invite a comfortable sit, stand or down. Say “stay,” reward in position after one second, then give the familiar release and invite movement. Mix immediate releases with tiny pauses. If the dog moves sooner, shorten the next pause; never put them back physically.','Holds the chosen position for three relaxed seconds and moves on release in 4 of 5 easy turns.','Use a one-second stand or a more comfortable surface. End rather than repeatedly resetting.'),
      ('One small step away','From the familiar short stay, shift one foot back, return immediately, and reward in position before releasing. Build one actual step away only after the shift is easy. Keep time short while movement is new, and face normally rather than looming or staring.','Stays comfortably through one step away and return in two short sessions.','Reduce to a weight shift. A stay is not a way to prevent retreat from something worrying.'),
      ('A modest everyday version','Alternate a brief stay while you turn slightly with an easier stationary pause. Change only one feature per turn. Build toward five to ten comfortable seconds or two steps away, returning to reward before release. Keep outdoor hazards and anxiety triggers outside this practice.','Responds to one stay cue through the chosen short duration and small movement in two easy sessions.','Keep either time or movement easier and record the actual version. Do not test out-of-sight endurance.')],deps=[['FREE-2',3]],maintenance=True)
    new('STOP','Stop and stand on cue','Foundations','Stop ordinary slow movement and remain standing for a brief moment.','Stop','An enclosed level space; no moving traffic. This cue never replaces a lead or secure boundary.',[
      ('Name a nearby stop','Walk slowly beside your dog. Say “stop,” stop your own feet, and use the familiar stand signal if needed. Reward a brief balanced stand at nose height, then invite walking again. Keep your hand loose and never use a lead to brake the dog.','Stops into a comfortable stand beside you on 4 of 5 slow indoor turns.','Start from one step of movement or reward a natural pause. Do not practice with a running dog.'),
      ('Fade your own stopping prompt','During a slow approach from one or two steps away, say “stop” before your small stand signal. Reward at the dog’s position as soon as they stop; walk to them rather than calling them out of the stand. Gradually reduce your extra body motion.','Stops from a short slow approach on the cue and small signal in two easy sessions.','Return to walking together. Reward immediately where the dog stopped instead of asking for a prolonged hold.'),
      ('A little distance, still easy','With the dog strolling in the secure space, cue a stop when they are only a few steps away and able to respond. Reward at their position, then release. Mix nearby practice with the slightly farther version and keep speed slow throughout.','Stops comfortably a few steps away on 4 of 5 quiet opportunities across two sessions.','Reduce distance. This practice does not certify an emergency stop near roads or wildlife.')],deps=[['STAND-1',3]],maintenance=True)
    new('FRONT','Come to a front position','Foundations','Finish a short approach facing you with space between your feet and the dog.','Front','Non-slip enclosed space. A stand is as valid as a sit; no tight positioning or collisions.',[
      ('Find the space in front','Stand still and use a small reward invitation to guide a broad approach toward the space in front of you. Mark when the dog faces you a comfortable step away and feed there. Reset to one side. Keep your knees soft and avoid drawing the dog into your legs.','Offers a balanced position facing you from either easy starting side.','Use a shorter straight approach and reward before the dog crowds you. Never push the shoulders into alignment.'),
      ('Name the front finish','Say “front,” then give the familiar empty-hand invitation. Reward facing you, then release to reset. Reduce the gesture across easy turns and vary the starting spot slightly. Keep this a position cue; a separate recall can bring the dog from farther away later.','Finds the front position from a few steps away without visible food in 4 of 5 turns across two sessions.','Keep the hand gesture or use one starting spot. Precision is optional; comfortable orientation is the goal.')],maintenance=True)
    new('FOODWAIT','Wait for a food-bowl invitation','Foundations','Pause briefly while a meal is placed and approach when invited.','Wait; eat','Use part of the normal meal and a quiet feeding area with one dog. Skip if food handling causes guarding or frustration; meals are never withheld for performance.',[
      ('A tiny pause before placement','Hold the bowl at a comfortable height while your dog stands freely nearby. Reward a moment with all paws on the floor, say “eat,” and place the bowl down within easy reach. Begin with almost no delay. Never repeatedly lift a bowl away as the dog approaches.','Comfortably pauses a moment and approaches the placed bowl after the invitation.','Feed the meal normally. Practice with a nearly empty bowl and a separate tiny reward another time.'),
      ('Lower once, then invite','Say “wait” before lowering the bowl a small amount, reward that brief pause, then say “eat” as you finish placing it. Gradually lower farther before the invitation, keeping the pause only a second or two. If the dog moves early, simplify the next turn without taking food away.','Waits comfortably through one calm bowl placement and approaches on invitation in two mealtimes.','Use a smaller lowering movement or an immediate invitation. No long waits, hovering hands over food, or interference while eating.')],maintenance=True)
    new('HEEL','Heel on cue','Walk skills','Move into a chosen position beside the handler and maintain it for a brief cued stretch.','Heel; free','Choose left or right once. Start in an enclosed non-slip room without a leash if safe. Shoulder roughly beside your leg, natural head carriage, no sustained eye contact or tight competition posture.',[
      ('Find the heel position','Stand still. Use a small treat invitation to bring the dog in a broad comfortable curve beside your chosen leg, facing the same way. Mark and feed at their natural head height when the shoulder is roughly alongside you. Release and reset away; do not squeeze them against your body.','Finds the chosen side facing forward on 4 of 5 easy invitations without strain.','Reward a looser side position or begin with the dog already beside you. Never pull them into place.'),
      ('Heel means come beside me','Say “heel,” pause briefly, then use the familiar empty-hand guide into position. Mark arrival and reward from the other hand. Practice from a step ahead and from the side, fading the guide gradually. Release after every arrival so the cue keeps a clear beginning and end.','Moves into the chosen side position on one heel cue with a small signal and no visible lure in two sessions.','Keep one easy starting angle and the clear hand signal. Do not add forward walking yet.'),
      ('Maintain position while moving','Cue the known heel entry, then take one slow step. Reward beside the same leg before the dog forges ahead, and release. Mix one, two and three steps, increasing only while shoulder position and natural movement stay easy. Feed frequently; this is brief precision work rather than an entire walk.','Enters and stays alongside for five to ten comfortable steps on most easy turns across two sessions.','Reward entry again or take just one step. Use natural head carriage rather than luring the head upward.'),
      ('Turns, stops and a clear release','After an easy heel entry, add one broad turn or a gentle halt, rewarding the maintained side position. Say “free” before allowing ordinary loose walking or sniffing. Transfer to a quiet secure outdoor spot with comfortable equipment, shortening the stretch again. Keep most walks available for exploring.','On cue, enters heel, follows a short stretch with one turn or halt, then leaves position on release in two easy settings.','Practice the turn standing beside you first or return indoors. A slack leash alone is loose walking, not the heel criterion.')],deps=[['FREE-2',2]],maintenance=True)
    new('RHYTHM','Counted walking rhythm','Walk skills','Join a short predictable count-and-reward walking game without a formal heel position.','One, two, three','A quiet safe space, suitable small rewards and room to opt out. Inspired by Leslie McDevitt’s counting pattern games; this is a predictable activity, not a cure for fear.',[
      ('Make the count predictable','While standing in a quiet space, say “one, two, three” in a gentle even rhythm and deliver a small reward beside you on “three.” Pause before repeating. Keep your hands neutral until delivery and make no demand for a sit, stare or exact side position.','Comfortably anticipates the reward near you at the end of the short spoken count across several brief turns.','Pair just “three” with a reward first or use a softer voice. Stop if anticipation becomes frantic.'),
      ('Walk a few counted steps','Begin the familiar count, take one or two ordinary steps and deliver the reward beside you on “three,” even if the position is approximate. Repeat only a few comfortable cycles, then finish with a break. Add a third step later. Keep distance from distractions rather than counting through fear or pulling the dog along.','Willingly joins two or three short count-and-walk cycles in two quiet outings, moving comfortably without leash pressure.','Count while stationary again or use just one step. Participation is optional and the reward timing stays predictable.')],maintenance=True)
    new('CURB','Pause at a curb','Walk skills','Stop with the handler before a ground-level pretend curb and wait for permission.','Curb; let’s go','Start with a flat line on a floor, then a quiet path well away from traffic. Humans always decide when a crossing is safe.',[
      ('Stop at a pretend edge','Place a flat contrasting strip across a non-slip floor. Approach slowly together, say “curb,” and stop before the line. Reward a brief stand beside you, then say “let’s go” and cross the harmless line together. Keep the route open and never block the dog with your knee.','Pauses beside you before the line in 4 of 5 slow approaches.','Use just one approach step and an immediate reward. Avoid raised poles or trip hazards.'),
      ('Transfer to a quiet real edge','Choose a quiet curb beside a protected area with no traffic exposure and generous space behind it. Use comfortable secure equipment, cue the familiar pause, reward, and turn away initially. Cross only where a human has checked safety. Reward pauses even when no crossing follows.','Pauses with you at the chosen quiet curb and waits for an invitation across two outings.','Return to the floor line. Recorded completion never means the dog can judge vehicles or cross alone.')],maintenance=True)
    new('CROSS','Cross a quiet road together','Walk skills','Combine a curb pause with a short uninterrupted crossing at the handler’s invitation.','Cross','A quiet lawful crossing with clear sight lines, comfortable fitted equipment and a capable adult. Rehearse away from vehicles first.',[
      ('Rehearse the whole path indoors','Mark two harmless flat lines several steps apart. Pause at the first as in curb practice, say “cross,” and walk straight to the far line with your dog on a slack lead. Reward on the far side. Keep the middle free of sniff rewards so the destination is clear.','Completes pause, invitation and a few continuous steps to the far line comfortably.','Shorten the pretend crossing or practice loose steps separately. No leash pressure to keep pace.'),
      ('One quiet checked crossing','At a suitable real crossing, keep the dog safely back from the edge while you check all directions. When the route is clear, say “cross” and walk together to a safe spot beyond the far curb. Reward there. If anything changes, prioritize human safety decisions over the exercise.','Completes the short human-managed crossing without stopping in the roadway in two quiet outings.','Return to the pretend route or choose a quieter place. Never rehearse against active traffic or rely on the cue for safety.')],deps=[['CURB-2',3],['LOOSE-2',3]],maintenance=True)
    new('SLOW','Match a slower walking pace','Walk skills','Keep a comfortable slack-leash pace when the handler deliberately slows down.','Slow','A short flat quiet route, suitable equipment and ordinary comfortable walking. This is pace matching, not restricting normal exercise.',[
      ('Notice a pace change','Walk a few familiar loose steps, say “slow,” and take one slightly shorter slower step. Reward at your side before the lead tightens. Return to your usual pace after a step or two. Keep the difference small enough for the dog to stay balanced without bracing.','Matches a small slowing change with slack equipment on most easy turns.','Make the change smaller or shorten the stretch. Stop for uneven movement or discomfort.'),
      ('Several unhurried steps','Cue “slow” before a short stretch of slower walking, rewarding intermittently beside you. Mix normal and slower stretches with an obvious return to ordinary walking. Try a few easy steps on another flat route only after the first location is clear.','Matches three to five slow steps after the cue across two comfortable outings.','Reward after one step again. This cue is not a demand for an unnatural gait or extended restricted movement.')],deps=[['LOOSE-2',3]],maintenance=True)
    new('WALKPAUSE','Pause while the handler stops','Walk skills','Stand comfortably nearby during a brief walking interruption without a formal heel or sit.','Pause; let’s go','A quiet protected walking space and comfortable secure equipment; no tethering or prolonged immobility.',[
      ('A one-second walking pause','Take a few ordinary steps, say “pause,” and stop with slack in the lead. Reward any comfortable nearby stand after one second, then invite movement again. No particular side or eye contact is needed. Reward before the dog becomes restless rather than waiting for frustration to stop.','Pauses near you for a second through several easy walking stops.','Shorten to a moment or practice in a secure room without a leash. Check ordinary toilet and movement needs first.'),
      ('A brief practical interruption','Repeat the known pause while you glance at an imaginary sign or adjust an empty pocket. Reward staying nearby, then say “let’s go.” Build toward five comfortable seconds, mixing shorter pauses in. Keep this brief and supervised rather than using a long stay in a busy area.','Comfortably waits nearby during a small five-second handler interruption across two quiet outings.','Reward sooner or remove the hand movement. Let the dog move and reset if the pause is difficult.')],maintenance=True)
    new('CRATE','Rest comfortably in a closed crate','Calm at home','Voluntarily enter a suitable crate and remain comfortable through a tiny attended door closure.','Crate; free','A roomy stable crate with a secured door and familiar bedding. Stay present. Skip confinement practice and seek individual help for panic; this does not establish alone-time tolerance.',[
      ('Choose to enter and exit','Secure the crate door fully open. Reward looking toward the entrance, then voluntary steps inside, placing rewards where the dog can reach without squeezing. Reward exits too. Build toward all four paws inside and turn around only if space allows. Never push, pull or close the door behind a hesitant dog.','Freely enters, turns comfortably and leaves, with willingness to return across two short sessions.','Remove the door or begin beside the opening. An open resting area is an equally valid choice.'),
      ('Door movement with an open exit','While the dog chooses to be inside, move the door an inch, reward, and open it fully again. Keep your body out of the exit. Slowly increase movement across short sessions; let any exit end the turn. The goal is comfortable door motion rather than keeping the dog inside.','Remains loose through gradual door movement and freely re-enters after breaks.','Move the door while the dog is outside first. Stop for vigilance, pawing, freezing or reluctance to return.'),
      ('A momentary attended closure','After easy full door movement, close and latch for less than a second, feed through safely, then reopen. Stay beside the crate and mix open-door turns with tiny closures. Build only a few comfortable seconds. Unlatch promptly at worry; never wait through distress for quiet.','Comfortable through several seconds of attended closure and willingly returns after an open-door break.','Return to open-door resting. Longer confinement, travel and absences each need a separate gradual plan.')])
    new('VACATE','Get off furniture on cue','Calm at home','Leave an allowed low resting surface voluntarily when invited.','Off','A low stable surface, non-slip landing and an unobstructed route. Use a ramp if needed. Skip for pain, sleep disturbance or resource guarding.',[
      ('Make leaving worthwhile','With the dog awake and comfortable on the low surface, place a reward on the safe landing or invite them down with a small lure. Mark as all feet reach the floor and reward there. Sometimes invite them back up if allowed so leaving does not always end access.','Voluntarily steps onto the safe landing in several relaxed repetitions.','Use a lower surface or reward a single step toward the exit. Never push, lift or grab a resting dog.'),
      ('Off before the invitation','Say “off,” pause, then give the familiar empty-hand gesture toward the safe route. Reward on the floor and offer another comfortable resting place. Gradually reduce the gesture, using one cue while the dog is awake. Keep the same secure landing throughout early practice.','Leaves the low surface on the cue with a small gesture and no visible food in two short sessions.','Keep the gesture and reward generously. Use management and individual help if approaches to furniture create tension.')],maintenance=True)
    new('ALLDONE','Finish an activity and move on','Calm at home','Recognize a clear end-of-game signal and transition to a different comfortable activity.','All done','Brief enjoyable play, a safe place to put props and a ready alternative such as water, a sniff or rest. Meet ordinary needs first.',[
      ('Predict a pleasant ending','During an easy short activity, stop while your dog is still comfortable. Say “all done,” put the prop aside without taking anything from their mouth, and offer the next quiet choice. Repeat on separate occasions. The phrase predicts an honest ending with support rather than abruptly removing all access to fun.','Moves comfortably into the offered alternative after several familiar endings.','Use a shorter activity or more appealing next option. First arrange a voluntary trade if the dog has the prop.'),
      ('Use the same ending elsewhere','Use the same phrase before ending a different easy activity, then open the route to the familiar alternative. Reward voluntary movement away and allow time to transition. Keep endings consistent and do not restart the game immediately after repeated requests; start another planned game later instead.','Recognizes the ending across two kinds of activity and can move on with ordinary support.','Return to the first familiar ending. Frustration means adjust the activity or transition, not withhold needed movement or rest.')],maintenance=True)
    new('HANDOFF','Change leash handlers comfortably','People and door','Stay comfortable while a walking lead passes between two familiar trusted adults.','With Alex (use the person’s name)','Two capable familiar adults, a secure enclosed rehearsal area and suitable equipment. Maintain human control of the lead throughout; no stranger handovers.',[
      ('Walk beside the helper','Walk together briefly while the usual handler keeps the lead and the familiar helper strolls at a comfortable distance. Let the helper reward a voluntary approach without reaching over the dog. End together. Keep departures and transfer of equipment out of this first exercise.','Comfortably walks near both adults and voluntarily accepts their company across two short turns.','Increase space or practice being together without walking. Do not use handover practice to force social contact.'),
      ('A still, secure transfer','Pause in the enclosed area. With the usual handler still holding the lead, let the helper take a secure hold at an appropriate point, then transfer control hand to hand without dropping it. Reward comfort, then transfer back. Keep hands away from the dog’s head and avoid tangling the line.','Remains comfortable through several quiet transfers with both adults staying nearby.','Make the hand motion smaller or reward the helper touching an unused spare lead first.'),
      ('A short walk with the new handler','Name the familiar helper before the known transfer. Let them invite one or two easy steps while the first adult remains close, then reward and reunite. Extend the short walk gradually without combining it with separation. The adult checks equipment security before any real-world transfer.','Walks a short comfortable route with either familiar handler after the transfer in two sessions.','Keep the first person beside the dog. Distress about separation needs its own supported plan.')])
    new('ELEVATOR','Ride a quiet elevator comfortably','Sounds and novelty','Choose entry and a short attended elevator ride with comfortable exits.','Lift (an invitation)','Use a quiet authorized elevator with a helper, non-slip footing and enough room. Keep dogs and equipment clear of door tracks; humans control access and never use the dog to hold doors.',[
      ('Watch from a comfortable distance','Stay well outside the doorway and let the empty elevator open and close while you reward comfortable observation. Move away after each brief look. Begin far enough back that sounds and people do not trap the dog. Skip crowded times and let the dog choose to leave.','Comfortably observes a few quiet door cycles and approaches only by choice.','Use more distance or stop at a partial view. Take another route when possible.'),
      ('Enter and exit while stationary','With a helper safely using the door controls according to building rules, invite a voluntary step into the stationary empty car. Reward and exit promptly together. Build toward a full brief entry with enough room to turn. Keep the lead slack and all feet clear of the moving-door zone.','Chooses full entry and a calm immediate exit in several stationary rehearsals.','Reward approaching from outside. Never lure a worried dog past a closing door.'),
      ('One short quiet ride','After easy entries, choose a single short ride with a familiar adult beside the dog. Reward comfort as the doors close and the car moves, then leave together at the next safe opening. Keep other people out of the training plan and finish after one ride.','Comfortably completes a short ride and ordinary exit on two quiet occasions.','Return to stationary entry or use an alternative route. Motion distress, nausea or panic calls for individual support.')])
    new('AUTODOOR','Pass through automatic doors','Sounds and novelty','Approach and walk through a wide automatic doorway without rushing or startling.','Through doors','A quiet permitted entrance with a helper, broad clearance and room to retreat. Humans verify the sensor and opening; avoid revolving doors.',[
      ('Watch the moving panels','Stand far enough to the side for an unobstructed view without triggering the doors yourself. Have a helper activate one cycle while you reward your dog for comfortable observation. Let them leave and return. Never put the dog in the opening to make the sensor respond.','Comfortably observes several predictable cycles with ordinary loose movement.','Watch from farther away or choose a quieter entrance. Motion comfort comes before passage.'),
      ('One generous walking pass','Have the helper safely activate the doors and confirm they are fully open. Invite your dog to walk beside you through the broad opening, reward beyond it, then take a break. Keep the lead and tail clear and walk at a natural pace, with room to abort before entry.','Walks through a fully open doorway comfortably in two short visits.','Return to observation or use a manual alternative. Never hurry a hesitant dog through narrowing panels.')])
    new('CLIP','Accept a leash clip','Care and equipment','Voluntarily remain comfortable while a lead is clipped and unclipped.','Clip?','Comfortable already-worn equipment, a quiet light clip and a freely accessible exit. Check fit separately; no reaching to grab the dog.',[
      ('Clip sound and hand approach','Hold the lead far enough away for comfort, operate the clip softly, then reward. Separately bring an empty hand a little toward the attachment point, reward and withdraw. Let the dog step away whenever wanted. Keep the sound and reach separate until both are easy.','Comfortable with the quiet clip sound and a short hand approach over several voluntary turns.','Muffle or replace a loud clip and increase distance. Do not touch equipment while the dog avoids you.'),
      ('Attach, reward, remove','Invite the dog near, briefly touch the familiar attachment area, reward and withdraw. After easy touches, attach the clip, reward, then remove it immediately. Keep the line supported so it does not swing into legs. Slowly add a few comfortable steps only when attachment itself is unremarkable.','Freely approaches for clipping and unclipping and moves comfortably afterward in two sessions.','Return to the hand approach or equipment comfort. Clipping is not permission to restrain a worried dog.')])
    new('COLLAR','Comfortable collar contact','Care and equipment','Stay relaxed through a brief gentle human touch of the collar or harness attachment area.','Got you (a gentle warning)','Well-fitted comfortable equipment and an awake willing dog. Touch only; no jerks, choking or surprise grabs. Useful for safe handling but not a test of restraint tolerance.',[
      ('Predict a brief touch','Say the chosen warning softly, reach only partway toward the equipment, reward and withdraw. Build toward a momentary finger contact on the outside without gripping. Keep your hand visible from the side, and let any movement away end the turn. Practice before a real need arises.','Voluntarily stays loose through several predicted brief outside touches.','Reach less far or use an easier body area. Skip and seek help for guarding or bite risk.'),
      ('A loose momentary hold','After easy contact, briefly place fingers around a safe section of equipment with no pressure on the neck or body. Reward and release immediately. Mix contact-only turns with this tiny hold. Never use a treat to conceal a grab or keep holding until the dog stops resisting.','Freely returns for predicted momentary no-pressure holds across two easy sessions.','Return to a touch. This does not make grabbing, lifting by equipment or restraint during fear safe.')])
    new('RINSE','Step into a shallow paw rinse','Care and equipment','Voluntarily place feet in a broad shallow tray of plain water.','Rinse','A broad stable non-slip tray, shallow lukewarm plain water, dry safe exits and healthy paws. No detergents or forced immersion; veterinary advice for skin problems.',[
      ('Explore the dry tray','Secure the broad tray so it cannot slide or wobble. Reward looking, approaching and voluntary foot contacts with the empty surface. Invite an easy step off after each contact. Build toward comfortable standing only if all feet fit with room; never place paws into the tray yourself.','Voluntarily steps into and out of the stable dry tray several times.','Use a flat non-slip mat or a wider tray. Stop at any uneven movement.'),
      ('A trace of water','Add only enough plain water to dampen a small area while the dog is away. Let them inspect and reward a voluntary single foot contact, then offer an immediate exit. Increase coverage only across comfortable turns. Keep water still, without pouring or splashing near the dog.','Chooses to place feet on the wet surface and freely returns after a break.','Use less water or return to a dry tray. Do not hold a foot in place.'),
      ('A short rinse pause','Invite the familiar tray entry with the chosen cue. Reward a brief comfortable stand in very shallow water, then invite an exit onto a dry non-slip surface. Any later wiping is a separate invitation. Empty the tray after use rather than leaving standing water accessible.','Enters on invitation, pauses comfortably and exits in two short sessions.','Rinse one willing foot briefly or use another vet-advised cleaning method. Stop for skin irritation or discomfort.')])
    new('EAR','Offer an outer-ear check','Care and equipment','Voluntarily participate in a tiny visual check of a healthy outer ear.','Ear?','Healthy pain-free ears, clean hands and a known chin start signal. No insertion, flushing, cleaning or medication in this lesson; contact a vet for pain, odor or discharge.',[
      ('Hand movement toward the ear','Offer the familiar chin target. While the dog chooses contact, move your other hand a little toward the outside of one healthy ear, stop and reward. End immediately if the chin lifts. Build only the comfortable hand approach, keeping fingers out of the canal.','Freely restarts and stays comfortable through the small hand approach in several turns.','Return to shoulder-level hand movement or the chin lesson. Do not investigate a painful ear through training.'),
      ('A momentary outer-flap view','After a voluntary start, touch only the outer flap lightly as demonstrated by your veterinary team, then withdraw and reward. If appropriate, briefly lift just enough for an outside visual look without stretching. Let a lifted chin end contact. Practice the other side separately from the easiest level.','Voluntarily permits a momentary healthy outer-ear view on each side across two easy sessions.','Return to approach or one light touch. No cotton buds, instruments or treatment without veterinary instruction.')],deps=[['CHIN-2',3]])
    new('SIDELIE','Lie comfortably on one side','Care and equipment','Choose a brief side-lying posture without being rolled or restrained.','Side','A broad soft non-slip surface and comfortable movement. Skip for stiffness or breathing difficulty. This posture is not permission for procedures.',[
      ('Reward a natural hip roll','While your dog chooses a comfortable down, quietly reward a natural hip shift or brief roll toward one side. Feed where the head can remain neutral rather than twisting the neck. Invite a break after one reward. Capture the movement without pushing shoulders or pulling legs.','Offers a comfortable hip roll toward side-lying during several voluntary turns.','Reward a smaller hip shift or simply watch for a natural side rest. Do not manipulate the body.'),
      ('Brief full side rest','From the familiar hip roll, reward a little more voluntary shoulder lowering until the dog chooses to rest on one side. Mark the brief posture and reward low, then allow them to get up. Work in tiny pieces and keep all limbs free.','Chooses a brief full side rest and rises comfortably across two short sessions.','Return to a hip shift or stop. Do not continue if rising looks difficult.'),
      ('Name the offered position','Say “side” just before the familiar comfortable movement or small empty-hand invitation. Reward a moment in position and release. Gradually use less help without adding duration or touch. Teach either comfortable side separately; a single willing side is sufficient for this optional cue.','Offers a brief side rest from the cue and small invitation in two sessions.','Keep capturing naturally offered rests. Any handling while side-lying needs a separate voluntary start and exit agreement.')],deps=[['DOWN-2',2]])
    new('RAMP','Walk a low stable ramp','Care and equipment','Choose slow up-and-down walking on a broad secured shallow ramp.','Ramp','A broad dog-suitable ramp with grip and side clearance, initially flat and later minimally inclined. Secure both ends. Get individual mobility advice for pain or weakness; no vehicle heights in this lesson.',[
      ('Walk the flat ramp','Lay the secured ramp flat on level ground. Reward a voluntary approach, then one foot contact and an easy step off. Build a complete slow walk along its broad center, rewarding partway if helpful. Let the dog go around it rather than steering with the lead.','Chooses relaxed complete passes in either direction on the flat secured ramp.','Use a wider flat surface or reward one foot contact. Stop for slipping or worry.'),
      ('A tiny supported slope','With the dog away, secure one end on a very low stable support according to the ramp instructions. Invite the familiar slow pass and reward balanced steps. Practice descent separately, starting near the bottom. A helper may stabilize equipment but never lift or push the dog along it.','Comfortably walks up and down the tiny stable slope across two sessions.','Flatten the ramp again. A higher vehicle ramp is a separate individualized transfer, not an automatic next test.')])
    new('SCRATCH','Scratch a designated board','Care and equipment','Voluntarily make a small front-paw scrape on a safe designated board.','Scratch','A stable broad board with a safe mild surface chosen with your veterinary or grooming team, no staples or loose grit. Healthy paws only. This teaches participation, not a nail-trimming prescription.',[
      ('Find one paw movement','Place the secured board nearly flat on a non-slip floor. Reward voluntary front-foot contact or a small paw movement on it, then reset off the board. Keep food above the surface or in your hand after marking; do not hide food underneath to provoke frantic digging.','Offers a small voluntary front-paw movement on the stable board without chewing or frustration.','Use a plain nonabrasive target first or reward a weight shift. Skip for sore pads or unwillingness.'),
      ('Name one gentle scrape','Reward the smallest deliberate paw scrape, then say “scratch” just before the familiar offer. End after one or two gentle actions and inspect paws and nails. Let a professional advise any later nail-care use; more scraping is not automatically better. Never lift or drag the paw over the surface.','Offers a gentle scrape on cue and readily steps away in two short sessions.','Use a nonabrasive board or return to foot contact. Stop for repeated hard scratching, irritation or uneven use.')])
    new('REAR','Rear feet on a flat target','Body awareness','Notice and place the rear feet on a broad flat target while walking forward.','Back feet','A long broad non-slip mat, lying flat with no raised platform. Comfortable ordinary movement only.',[
      ('Notice the rear-foot arrival','Lay a broad flat mat across an open walking route. Let the dog stroll forward over it, marking when a rear foot reaches the mat. Reward at a natural head height while the rear feet are still on the surface if possible. Keep walking routes roomy and avoid sudden stops.','Offers several relaxed passes with reward timed to rear-foot contact.','Use a longer mat and slower approach. Do not move a paw or block forward escape.'),
      ('Pause with rear feet supported','Use the same easy forward pass and reward when both rear feet are on the mat after the front feet have stepped beyond it. Feed in a balanced stand, then release forward. Choose a target long enough that the position happens comfortably without stretching the body.','Briefly stands with rear feet on the mat and front feet beyond in several easy turns.','Reward any rear contact or make the mat longer. Stop for stiffness or uneven loading.'),
      ('Name the target position','Say “back feet” before the familiar slow pass and brief pause. Reduce your own accompanying movement while keeping the route straight. Reward both rear feet on the flat surface, then release. This lesson ends at floor level; no raised perch or balance surface is required.','Finds the rear-foot position on the cue and small guiding gesture in two short sessions.','Keep walking with the dog or reward a single rear contact. Skip if the posture is difficult.')])
    new('SIDESTEP','Take a sideways step','Body awareness','Make one or two small voluntary lateral steps without being crowded.','Side step','Open non-slip space with room to move away. Work both directions separately without demanding symmetry or using body pressure.',[
      ('Capture a lateral foot shift','Stand at an angle beside your comfortable standing dog, leaving generous space. Watch for a small sideways foot adjustment during an ordinary reset, mark and reward. A small reward invitation across the front can help, but do not walk into the dog or twist the head sharply.','Offers several small lateral foot adjustments with balanced ordinary movement.','Reward a tiny weight shift or try another day. Do not create the movement by crowding or pushing.'),
      ('Build and name one step','Reward slightly larger sideways adjustments until a front and rear foot move a small distance in the same direction. Say “side step” just before the familiar small gesture. Keep your feet still, mark one balanced step and release. Teach the other direction in a separate easy session if comfortable.','Offers one or two balanced lateral steps from the cue and small gesture in two sessions.','Reward a single foot movement again. End for stiffness, scrambling or persistent turning instead of stepping.')])
    new('PIVOT','Move the rear feet around a flat target','Body awareness','Keep front feet on a broad flat mat while taking one or two small rear-foot steps around it.','Pivot','A broad non-slip floor target, open space and healthy comfortable movement. No raised perch, tight rotations or long repetitions.',[
      ('Reward a tiny rear adjustment','Invite the known front-feet target position. Keep rewards near natural head height and watch for one small rear-foot adjustment while the front feet remain on the mat. Mark immediately and release. Do not turn the head far to force the hindquarters around or step into the dog.','Offers several small balanced rear-foot adjustments with front feet supported on the flat mat.','Use a larger mat or reward a weight shift. Skip if the dog repeatedly loses balance.'),
      ('A small arc on cue','Reward one rear step around the familiar front-foot position, then a second on a later turn. Put “pivot” before the predictable small invitation. Mix single-step rewards with two-step attempts and release often. Keep the arc short; there is no need for a full circle.','Makes one or two comfortable rear-foot steps around the flat target on invitation across two sessions.','Return to a single adjustment. Stop for twisting, paw sticking or any difficulty moving freely.')],deps=[['FEET-3',3]])
    new('UNDER','Walk under a roomy obstacle','Body awareness','Choose to walk beneath a high stable open structure without crouching.','Under','A stable open table or broad arch with generous head and body clearance, no low bars, dangling objects or enclosed dead ends.',[
      ('Explore the open route','Stand beside a broad high table or arch and reward a voluntary look toward the open path beneath. Place an easy reward invitation just inside, then outside again. Keep both ends clear and allow the dog to go around. Never lower the structure over the dog or lure them into a cramped space.','Comfortably takes voluntary steps beneath the roomy open structure and exits freely.','Use a higher wider opening or stay at the edge. No crawling or crouching is needed.'),
      ('Name a walking pass','Say “under,” then give the familiar small invitation along the clear route. Reward after a complete natural-height walking pass. Hide the reward until afterward as the gesture becomes familiar. Reset well away and finish after a few easy choices rather than repeatedly sending the dog back and forth.','Walks underneath on cue and a small gesture in two short sessions without ducking or rushing.','Use a clearer invitation or wider route. Choose a different activity if overhead structures worry the dog.')])
    new('POLES','Step over ground poles','Body awareness','Walk slowly over a few safe poles lying on the ground with natural foot placement.','Step over','Two or three broad visible poles that cannot roll, completely on the floor, with generous spacing for this dog. Non-slip footing and comfortable movement; no jumping or fitness prescription.',[
      ('One harmless pole','Secure one visible pole flat on the ground. Walk beside it first, then invite a slow voluntary step across, rewarding beyond it. Let the dog inspect or walk around instead. Choose a pole and approach angle that allow normal walking without hopping, snagging toes or pulling on equipment.','Comfortably walks over the single ground pole in either direction over several turns.','Use a flat contrasting strip instead or remove the obstacle. Stop for tripping or uneven movement.'),
      ('A short spaced line','Add a second secured ground pole far enough away for several natural steps between them. Invite an unhurried pass and reward at the end. Add a third only if walking stays ordinary. Adjust spacing to the dog rather than asking them to match a rigid pattern.','Chooses a slow balanced pass over two or three well-spaced ground poles across two sessions.','Remove one pole or increase spacing. No raised poles, repetitive circuits or forced stride changes.')])
    new('SURFACE','Choose unfamiliar safe surfaces','Body awareness','Voluntarily step across a small stable change of texture.','Explore (an invitation)','Clean secure non-slip textures such as rubber and tightly secured fabric on the floor. No hot, sharp, noisy unstable or painful surfaces.',[
      ('One foot on a new texture','Lay a small secured texture beside familiar flooring. Reward looking or approaching from the familiar side, then voluntary foot contact. Offer an easy reward back on the original surface so moving away remains part of the game. Never place the dog onto it or trap the exit.','Freely chooses single-foot contacts and returns after easy breaks.','Use a smaller or more familiar texture. Reward interest without expecting contact.'),
      ('A short voluntary crossing','Use the familiar texture over a small broad patch. Invite a natural walking crossing, reward beyond it and give a break. Later present a different safe texture from the easiest level, without assuming transfer. Keep your invitation optional; comfort matters more than covering a required area.','Chooses comfortable full crossings on two different stable safe textures in separate easy sessions.','Return to one foot or remove the unfamiliar patch. Avoid luring into a situation the dog then cannot leave.')])
    new('CROSSPAW','Rest with crossed front paws','Clever companions','Offer one light front-paw crossing while lying comfortably.','Cross paws','A broad soft non-slip surface, comfortable down and a small willing paw offer. Skip if shoulders, elbows or wrists are uncomfortable; no held or forced crossing.',[
      ('A tiny reach in a down','With the dog in a comfortable down, offer the familiar low paw hand just a little toward the midline. Mark a tiny voluntary reach and let the paw return immediately. Reward without holding the foot or asking the dog to lean sideways. Keep early turns to one small reach.','Comfortably reaches the chosen paw slightly inward without shifting awkwardly or rising.','Offer the hand closer to the paw or reward a small lift. Never drag the leg across.'),
      ('Fade the receiving hand','Offer the same small inward invitation but lower your hand before contact so the dog can place the paw lightly across the other foreleg if comfortable. Mark the brief placement and release. Add “cross paws” before the invitation, fading the hand only across easy balanced turns.','Offers a brief voluntary light crossing from a cue and small signal across two sessions.','Reward the smaller reach again or skip the trick. A stretched, trapped or held leg is outside the goal.')],deps=[['DOWN-2',2],['PAW-1',3]],priority='Optional trick')
    new('TILT','A little head tilt','Clever companions','Put an optional cue to a naturally offered small head tilt.','Tilt','Quiet familiar surroundings; capture only natural comfortable movement. No startling noises or repeated unusual sounds to provoke it.',[
      ('Capture a natural tilt','During ordinary friendly interaction, watch for a naturally offered small head tilt. Quietly mark it and reward while the dog returns to neutral. Pause rather than trying to repeat noises until the dog tilts. A few occasional captured moments across days are enough to explore the game.','Several comfortable naturally offered tilts can be rewarded without provoking worry.','Choose another trick if tilts are rare. Persistent new or one-sided head tilting needs veterinary assessment.'),
      ('Offer the new cue','Once the dog begins offering the small movement in the game, say “tilt” just before a likely offer. Reward one brief tilt, then finish or reset to neutral. Try the cue once on an easy turn and help by waiting calmly rather than exaggerating sounds or posture.','Offers a small comfortable tilt after the cue in several short enjoyable turns.','Return to occasional capturing. No physical positioning or requirement to tilt farther or hold the angle.')],priority='Optional trick')
    new('SHAKEOFF','Shake off on cue','Clever companions','Name a naturally occurring comfortable body shake without wetting or startling the dog.','Shake off','Capture ordinary comfortable shakes only. Do not use stress, water sprays, restraint or irritating objects to produce them.',[
      ('Catch an ordinary shake','Notice a naturally occurring shake after an ordinary comfortable transition, such as getting up after rest. Quietly mark after the motion and reward. Keep your distance so you do not interrupt the movement. Record only easy opportunities rather than provoking repeated shakes during one session.','You can reward several ordinary shakes without changing the dog’s comfort or daily routine.','Skip the game if there are no natural opportunities. Frequent unexplained shaking or scratching needs a health check.'),
      ('Name before the familiar moment','Say “shake off” when an ordinary shake is predictably about to begin, then reward afterward. Across days, try the cue once in that same comfortable context. Accept no response and move on; this is an optional captured action, not a way to make fear or tension disappear.','The cue precedes a comfortable voluntary shake in several familiar-context opportunities.','Continue occasional capture only. Never treat a shake as proof of emotional recovery or add unpleasant triggers to produce one.')],priority='Optional trick')
    new('CIRCLEME','Circle around the handler','Clever companions','Walk one broad loop around a stationary person.','Circle','Open non-slip space and a steady standing or seated handler; generous clearance, no moving feet or tight curves.',[
      ('One open half-loop','Keep your body still and offer the known hand target to one side, then farther around at generous distance. Reward after a quarter or half-loop. Let the dog take a broad path without brushing your legs. Pass the invitation between hands smoothly rather than turning your body into their route.','Completes either comfortable half of the broad loop with easy hand targets.','Reward a smaller arc or use a seated steady handler with room around the chair.'),
      ('Join and name the circle','Invite the first familiar half-loop and switch to the other hand for the remaining half. Reward halfway initially, then after a full comfortable loop. Say “circle” before the first invitation and gradually reduce target help. Finish with the dog clear of your feet.','Walks one broad loop from the cue and small signals in two short sessions.','Reward halfway again. Keep speed slow and stop if either participant feels unsteady.')],deps=[['TOUCH-2',3]],priority='Optional trick')
    new('UNROLL','Unroll a short mat','Clever companions','Nudge a loosely rolled mat forward to reveal a small flat section.','Unroll','A lightweight non-slip mat with a very loose broad roll, no straps, food hidden inside or material the dog chews. Supervise and remove after practice.',[
      ('Nudge the loose edge','Set only the first few inches of the mat in a loose roll, keeping the rest flat and secured. Present a familiar large nose target against the front of the roll. Reward a gentle touch, then a touch that moves it slightly. Keep your hands clear and stop before pawing or biting starts.','Gently nudges the roll so a small section opens without mouthing or pouncing.','Loosen the roll further or return to an ordinary object target. Skip for fabric chewers.'),
      ('A short unrolling action','Reduce the target pad while rewarding the same gentle forward nose nudge. Add “unroll” before the familiar action. Start with one movement, then two on a later turn. Reward after the small section is flat, remove the prop and finish; the whole mat need not be unrolled.','Opens a short loose section on cue with one or two gentle nose nudges across two sessions.','Use the larger pad or only one nudge. Never increase roll resistance or encourage forceful pushing.')],deps=[['OTARGET-2',3]],priority='Optional trick')
    new('LEFTRIGHT','Choose left or right targets','Clever companions','Follow two distinct directional cues to nearby matching floor targets.','Left; right','Two identical broad flat targets, equal short distances on each side. Directions are from the dog’s starting orientation, with no reading or reasoning claim.',[
      ('Pair left by itself','Use one familiar mat a single step to the dog’s left from a consistent forward-facing start. Say “left” before the ordinary mat invitation, then reward arrival. Reset facing the original direction and fade the gesture. Keep the right target out of view during this independent pairing.','Moves to the left target on the new cue with reduced mat prompting in several easy turns.','Move the target closer and use the known mat cue again. Keep orientation consistent.'),
      ('Pair right independently','With the left mat put away, place the familiar target one step to the dog’s right. Say “right” before the known mat invitation and reward arrival. Keep starts facing forward, then fade the extra cue over brief separate sessions. This side can be learned before the left pairing is finished.','Moves to the right target on its cue with reduced mat prompting in several easy turns.','Return to the known mat invitation. Do not alternate words rapidly or test two targets yet.',[['MAT-2',3]]),
      ('Make a fair directional choice','Place both identical targets equally near. Begin centered with neutral hands and gaze, request one direction, and reward the corresponding arrival. Mix requested sides and reset orientation each time. After errors return to a single-target success. Record responses without interpreting a lucky sequence as general left-right knowledge.','Chooses the requested nearby target on most turns across two short mixed-order sessions.','Separate the pairings again or keep pointing help. This criterion concerns the practiced orientation only.',[['LEFTRIGHT-1',3],['LEFTRIGHT-2',3]])],deps=[['MAT-2',3]],priority='Optional trick')
    new('NOD','A small nose-target nod','Clever companions','Offer a tiny comfortable down-and-up nose movement from a cue.','Nod','A broad safe target, natural neck range and brief turns. No repeated bobbing, head pressure or exaggerated flexion.',[
      ('Two close target positions','Present the known nose target at natural head height and reward. On another turn present it only slightly lower, still comfortable, and reward. Mix the two nearby placements without asking the dog to tuck the chin or stretch. Let the head return to neutral freely between touches.','Comfortably follows the two very close target heights with a small natural head motion.','Use an even smaller change or stay at natural height. Skip for neck stiffness.'),
      ('Fade to a tiny nod signal','Invite a small lower-then-neutral movement with the familiar target, rewarding one comfortable motion. Say “nod” just before it and gradually make the pad help smaller. End after one or two turns. The finished trick is a small motion, not agreement with a question.','Offers one small comfortable nod from the cue and small signal in two short sessions.','Keep the pad visible or choose another trick. Never request a deeper bend or a long sequence of nods.')],deps=[['OTARGET-2',3]],priority='Optional trick')
    new('TOILETBELL','Ring to request a toilet trip','Useful little jobs','Use a quiet accessible button to request prompt supervised access to the toilet area.','Outside? (the button predicts a trip)','A large low-force quiet button at a comfortable nose height near the exit, inaccessible electronics and prompt adult response. A request never replaces regular toilet opportunities.',[
      ('Connect one press with access','Place the familiar quiet button near the usual toilet exit. During a planned trip, invite one known press, immediately say “outside,” and provide the ordinary supervised trip. Reward toileting as usual. Do not require pressing before urgent access or repeat button drills without opening the route.','Several comfortable press-to-trip pairings have occurred with prompt consistent human follow-through.','Use an ordinary approach-to-door request instead. Give the toilet opportunity whether or not the button is pressed.'),
      ('Notice an offered request','At a normal likely toilet time, stand near the button briefly with neutral hands. If the dog offers a press, promptly open the safe route and accompany them. If not, offer the trip anyway. Respond to early spontaneous presses with calm access instead of testing whether they really need it.','Offers a press without a hand prompt on several occasions and receives a prompt trip.','Return to occasional prompted pairings. Check schedule and health rather than withholding access after frequent requests.'),
      ('Make the request practical','Keep the button in the same accessible place and respond consistently during ordinary supervised days. Record requests and whether toileting followed so you can improve access timing. The action requests an opportunity; it does not prove bladder urgency or language understanding. Continue regular trips and other recognized signals.','Uses the button independently for access across two days while the human keeps a reliable toilet routine.','Use a simpler door approach signal or return to scheduled access. New accidents or sudden frequency changes need veterinary attention.')],deps=[['BUTTON-3',3]])
    new('LIGHTPAD','Turn on a lamp with a pad','Useful little jobs','Press an approved low-force control to turn on a small safe lamp.','Light','A commercially safe accessible low-voltage or wireless control pad, secured wiring and electronics out of reach. Humans configure and inspect the lamp; no plugs, wall switches or electrical DIY by the dog.',[
      ('Light change is comfortable','Let a helper turn the lamp on and off with the dog at a comfortable distance. Reward a noticed mild change, then take a break. Keep the room otherwise lit so switching does not plunge the dog into darkness. Teach this comfort separately from pressing the control pad.','Comfortable with several gentle lamp changes and free movement away.','Use a dimmer familiar lamp or more distance. Stop for light sensitivity or startle.',[]),
      ('Transfer the known pad press','With the lamp temporarily disconnected from the control, secure the approved pad at natural nose height. Invite the familiar gentle press and reward. Match the old target’s location initially, then move it only slightly. Keep all switches, batteries and wires inaccessible to mouthing.','Offers comfortable gentle presses on the secured control in several turns.','Use the old pad beside the new one or choose a more sensitive approved control.',[['BUTTON-3',3]]),
      ('One press makes light','After both separate pieces are comfortable, enable the lamp control. Say “light,” invite one known press, and reward after the gentle light change. A human resets the lamp between turns; reward the dog’s single action rather than repeated toggling. Remove access after the short supervised practice.','Turns on the safe lamp from the cue with reduced press prompting in two short sessions.','Return to disconnected presses or human-controlled light changes. Stop for mouthing, repeated rapid presses or startle.',[['LIGHTPAD-1',3],['LIGHTPAD-2',3]])])
    new('BLANKET','Pull a lap blanket into place','Useful little jobs','Gently pull a loose lightweight blanket edge toward an adult’s lap.','Blanket','A consenting seated adult, a light loose blanket with a safe broad grip edge and non-slip footing. No cords, knots, trapped limbs or blanket wrapping around the dog; skip for fabric eaters.',[
      ('A free blanket edge','Support a lightweight blanket loosely on a low stable chair with its broad safe edge at natural mouth height. Invite the known gentle grip and tiny pull, then a release and reward. Let the fabric slide with almost no resistance. Keep all feet and neck clear of loose material.','Comfortably moves the loose fabric an inch or two and releases in several turns.','Use an ordinary safe pull prop or support more of the blanket. Skip if chewing begins.'),
      ('A tiny lap adjustment','With an adult seated and the blanket loosely over their knees, offer the same free edge beside the lap, away from hands and feet. Cue the gentle pull toward the adult, release and reward immediately. The adult helps the fabric travel so no force or backward dragging is needed.','Makes a small comfortable blanket adjustment without contact with limbs or loss of footing.','Return to the empty-chair version. Never ask the dog to pull a person, weighted blanket or caught fabric.'),
      ('Name the short job','Say “blanket” before the familiar tiny pull invitation. Reward a single useful adjustment and release, then the adult finishes positioning the blanket. Reduce the extra prompt while the movement remains light. Finish after one job rather than repeatedly disturbing the blanket to get more repetitions.','Makes one gentle useful lap adjustment on cue and releases across two sessions.','Keep helping the blanket slide or choose a different job. Remove fabric after any chewing or snagging.')],deps=[['PULL-2',3]])
    new('SCENTMATCH','Choose a familiar human scent','Scent adventures','Explore matching a familiar adult’s scent across safe inaccessible samples.','Find this scent','One willing familiar adult, large identical ventilated containers with secured lids, clean cotton samples and clean handling tools. No essential oils, chemicals or ingestible loose samples. One dog at a time; this is a game, not detection certification.',[
      ('A pleasant scent-container pairing','Let a familiar adult handle a clean cotton sample, then secure it inside a large vented container the dog cannot open or mouth. Present the container still and reward a voluntary sniff nearby from your hand. Put it away between turns. Keep rewards outside so scent and food are not stored together.','Comfortably investigates the safe container during several brief rewarding presentations.','Use a larger secured container or reward looking first. Stop for biting or frustrated pawing.'),
      ('Introduce a clean comparison','Using clean tools, prepare one identical container with an untouched cotton sample and one with the familiar adult’s sample. Present them close and equally accessible. Reward investigation of the familiar sample; move it between positions and reset errors to one easy target presentation without correction.','Comfortably chooses to investigate the familiar sample more often than a fixed side across easy mixed positions.','Return to one container, use fresher samples and check accidental food odors or handling differences.'),
      ('Refresh the samples fairly','Prepare fresh matched cotton samples and swap container positions with a helper while you stay neutral. Briefly offer a separate secured reference sample from the same adult, then invite the close choice. Reward the matching sample and record choices before making claims about scent understanding.','Most choices follow the familiar adult’s fresh sample across two short mixed-position sets with neutral human cues.','Keep the one-sample sniff game. A small household exercise does not establish operational detection or general matching ability.')],priority='Enrichment')
    new('TRACKPERSON','Follow a short human trail','Scent adventures','Follow a short fresh route laid by a familiar adult, using investigation rather than seeing their departure.','Track','Two familiar adults, a safe open low-distraction area, a secured familiar-human cotton scent sample and comfortable equipment if needed. Food stays at the finish, not along the route. No roads, forced separation or real missing-person searches.',[
      ('A very short visible route','Have a familiar adult walk a straight route of a few metres across clear safe ground and wait in view. Invite the dog to investigate from the start and follow at their pace, rewarding at the adult. Record the route beforehand. This visible introduction builds enjoyment rather than establishing tracking ability.','Comfortably investigates along the tiny route and enjoys the reward at the familiar adult.','Keep the adult closer or walk together. Skip if even brief distance causes distress.'),
      ('Start a fresh unobserved trail','Let the dog remain comfortably with you while the other adult walks a fresh short straight route out of their view and waits just behind a broad safe screen. Offer a secured scent sample handled by that adult at the start, then say “track.” Follow relaxed investigation without pointing or steering; reveal the endpoint before frustration.','Investigates from the start and follows the short freshly laid route toward the hidden endpoint on several easy turns.','Restore a visible finish or shorten the route. Do not hold the dog back, drag along the route or keep a helper hidden while distress develops.',[['TRACKPERSON-1',3],['SCENTMATCH-1',3]]),
      ('One fresh broad bend','Have the adult lay a fresh route of roughly five to ten metres with one broad bend while the dog cannot see the departure. Mark the route for the humans and keep the finish easy. Invite from the scent sample at the start, follow without directional help and reward at the adult. If the dog takes a direct shortcut, simplify rather than counting it as route-following.','Across two short sessions, willingly follows the approximate fresh route including its bend to the hidden adult. This is a small practiced trail, not evidence of operational tracking ability.','Return to a shorter straight trail or a visible finish. Keep trails fresh and easy; no aged tracks, unknown people or prolonged searches.')],priority='Enrichment')
    new('SCENTINDICATE','Show a find with a quiet nose hover','Scent adventures','Offer a brief nose hover beside a safe secured scent container instead of grabbing it.','Show me','A large secured vented container with a familiar human cotton scent sample inside. No oils or loose samples. Comfortable natural head height, no prolonged breath holding or sustained nose pressure.',[
      ('Reward a brief investigation','Present the familiar secured scent container at an easy natural height. Mark the first brief nose investigation before licking, pawing or grabbing starts, reward away and reset. Keep turns short and reward early. The container stays fixed rather than being pushed into the dog’s face.','Offers gentle brief investigation without mouthing or pawing in several easy turns.','Reward a glance or approach from farther away. Remove the prop if chewing or frustration starts.'),
      ('A still moment beside the scent','After easy investigation, delay the marker by only a fraction of a second while the nose remains near the container. Reward before the dog presses or paws. Name the short hover “show me,” then reset away. Build to about one second at most, mixing immediate rewards in.','Offers a brief relaxed nose hover beside the container on invitation across two sessions.','Mark sooner and reward one soft investigation. Do not demand contact, a rigid freeze or a long hold.')],priority='Enrichment')
    new('ARTICLE','Find a familiar scented article','Scent adventures','Locate a safe familiar-human-scented container in a small accessible area without retrieving it.','Find the article','A large secured vented container holding clean cotton handled by one familiar adult, safe open hiding places and no accessible samples, oils or food inside. This is recreational searching.',[
      ('An obvious scent destination','Present the familiar scent container on a clear floor while the dog watches. Say “find the article,” allow approach and investigation, and reward beside it from your hand. Leave the container where it is rather than inviting pickup. Move the obvious position slightly between short turns.','Comfortably locates and investigates the visible container without trying to retrieve it.','Keep it near your feet or reward a glance first. Secure the container or stop if it is mouthed.'),
      ('A small concealed search','Let the dog watch the familiar container placed partly behind a broad safe object. Invite the search, remain neutral and reward discovery beside the container. Later make one easy placement while the dog looks away nearby. Keep the area tiny and reveal the container before frustration develops.','Willingly finds the container at several easy partly hidden placements across two sessions.','Show more of the container or use a visible placement. No inaccessible cavities, climbing or prolonged searching.')],deps=[['SCENTMATCH-1',3]],priority='Enrichment')
    new('POINT','Follow a pointing gesture','Clever companions','Use a human pointing gesture to approach one of two nearby floor targets.','A clear arm point','Two identical broad flat targets in a quiet space. Handler points without leaning over or crowding; this is learned cue-following rather than a claim about reasoning.',[
      ('Point to one familiar target','Place one familiar mat a step away. Point clearly toward it, then give the known mat cue and reward arrival. Reset nearby and move the single mat slightly between turns. Gradually pause after pointing so the dog can approach before hearing the old cue.','Approaches the single target after the gesture with reduced verbal help across easy positions.','Keep the mat closer and pair gesture then old cue again. Use a comfortable visible arm motion.'),
      ('Choose between two close targets','Place two identical mats equally near, point clearly to one, and reward the indicated arrival. Alternate sides in mixed order while keeping your feet and gaze neutral. After errors return to the single-target pairing rather than pointing repeatedly or correcting. Keep only one invitation per turn.','Usually chooses the pointed-to close target across two short mixed-side sessions.','Use a more obvious gesture or return to one mat. Do not infer abstract understanding from a small test.')],deps=[['MAT-2',3]],priority='Optional trick')
    new('BREAKBUTTON','Press to request a break','Care and equipment','Learn a separate optional button action that reliably ends a short training turn.','Break (the button’s consequence)','A large quiet low-force button, different from other request controls, within easy reach and out of chewing access. All ordinary withdrawal remains valid; never require a button press to stop.',[
      ('A press always opens a break','In a short easy training session, invite one familiar press on the designated quiet break button. Immediately say “break,” stop asking for actions and let the dog walk away, sniff or rest. Follow through every time. Keep rewards and attention available without demanding a return to work.','Several gentle prompted presses have consistently produced an immediate optional break.','End the session without a press. Use a different easy signal if the button is uncomfortable.'),
      ('Wait for a voluntary request','During an easy familiar activity, leave the break button safely accessible and pause briefly with neutral hands. Honor any offered press immediately. Also stop at ordinary avoidance, disengagement or movement away. Continue pairing on later short sessions without manufacturing frustration to make the dog request relief.','Offers the separate break press voluntarily on several occasions and the person promptly stops the turn.','Keep an occasional prompted pairing or simply use natural withdrawal. No response is required for the dog to have a break.')],deps=[['BUTTON-3',3]])
    new('DIG','Dig in a designated patch','Scent adventures','Enjoy digging only in a clearly offered safe supervised patch.','Dig here','A clean broad shallow digging area with soft suitable material, no sharp pieces or buried food for eaters, and room to leave. Inspect paws and keep dogs separate.',[
      ('Explore the permitted patch','Show the clean shallow patch and let the dog investigate freely. If they offer one comfortable paw scrape, say “dig here,” reward beside the patch and let them explore again. Use an obvious safe favorite toy on the surface if helpful, without burying food or provoking frantic digging.','Comfortably explores and offers a little voluntary digging in the patch.','Accept sniffing or ordinary play instead. Some dogs do not enjoy digging; do not move their paws.'),
      ('Invite and finish the digging game','Offer “dig here” before access to the familiar patch and reward a little appropriate digging with continued choice. End after a brief enjoyable turn with a clear finished cue and another pleasant activity. Cover or block the patch afterward. Supervise rather than assuming this cue prevents digging elsewhere.','Chooses a short comfortable dig in the offered patch and transitions away across two sessions.','Shorten the turn or use sniffing enrichment. Stop for gritty eyes, sore paws, swallowing material or escalating arousal.')],priority='Enrichment')
    new('RALLY','A little rally route','Brainiacs','Follow a short handler-directed route combining heel, a position pause and a broad marker loop.','Rally','A spacious non-slip enclosed area and three clear human-readable stations. No competition precision, tight turns or speed requirement.',[
      ('Heel to one easy station','Set one station card several steps away. Cue the familiar heel entry, walk a short comfortable stretch, release at the card and reward. Rehearse stopping and choosing an ordinary stand separately at the station. Keep the card for the human; the dog is responding to your cues.','Comfortably travels in a short heel to the first station and transitions to a brief stand.','Shorten the route and reward the heel entry. Leave other station actions out initially.'),
      ('Add a marker-loop station','Place a familiar soft cone with generous clearance after the first station. Release the heel, cue the known broad loop and reward its finish. Practice the cone station on its own as well as after the first. Keep your cues distinct so the dog is not asked to heel and loop simultaneously.','Comfortably changes from the first station into a separately cued broad loop.','Reward each station separately or remove the connecting walk. Use a wider cone curve.',[['RALLY-1',3],['CONE-2',3]]),
      ('One short complete route','Add a final station for the familiar comfortable stand and release. Follow the three stations at a natural pace, rewarding between them whenever useful. On later sessions change the station order with the same clear cues. Finish after one enjoyable route and remove the cards.','Completes the short handler-directed route with clear heel, loop, position and release cues in two easy sessions.','Keep two stations or reward every action. This is a cooperative activity rather than a test of memorized sequences.')],deps=[['HEEL-3',3],['STAND-1',3]],priority='Optional advanced')
    D['skills'][-1]['project']={'modules':[{'code':'HEEL'},{'code':'STAND'},{'code':'CONE'},{'code':'RALLY'}],'foundations':['FREE']}
    new('CIRCUIT','A floor-level adventure circuit','Brainiacs','Join a few voluntary walking obstacles into one short adaptable route.','Adventure','A wide floor-level hoop, a very short secured open tunnel and ground poles in a spacious non-slip area. All equipment has easy bypasses. No jumps, speed, tight turns or fitness prescription.',[
      ('Link two familiar walking pieces','Place the familiar floor hoop and the shortest open tunnel far apart with an easy straight walking connection. Invite one hoop pass, reward, then separately invite the tunnel and reward. Let the dog bypass either. Start with each obstacle alone before asking for a linked route.','Comfortably chooses both familiar walking pieces with a relaxed connection.','Use only the easier piece or reward the connection. Remove any obstacle that creates rushing.'),
      ('Add the ground-pole finish','After a break, add the familiar widely spaced ground poles beyond the tunnel with generous straight clearance. Rehearse this last part alone first. Then invite the short route, rewarding after each piece. Keep the dog walking naturally; a complete circuit is optional on every turn.','Comfortably adds the ground-pole walking finish without rushing or changing gait.','Use one pole or skip that piece. Never guide the dog into an obstacle they are trying to avoid.',[['CIRCUIT-1',3],['POLES-2',3]]),
      ('An adaptable route with choices','Say the adventure invitation before the first familiar component cue. Support each choice separately, reward generously and finish after one easy circuit. On another day change only the order with large open connections. Preserve all bypasses and celebrate a shorter route when the dog prefers it.','Enjoys a short linked route on two occasions with natural movement and willing entries at every piece.','Return to separate obstacles or choose a single comfortable walking activity. No repeated circuits to meet a quota.')],deps=[['HOOP-2',3],['TUNNEL-2',3]],priority='Optional advanced')
    D['skills'][-1]['project']={'modules':[{'code':'HOOP'},{'code':'TUNNEL'},{'code':'POLES'},{'code':'CIRCUIT'}],'foundations':[]}
    new('SCENTREPORT','Find, show and report a scent','Brainiacs','Find the familiar scent container, indicate it briefly, then return to touch the handler’s hand.','Report','One secured familiar human-scent container, easy accessible placements and an uncluttered room. No oils, operational searches or prolonged indication.',[
      ('Join the find and indication','Place the familiar container in a fully visible nearby spot. Invite the known article search, then the short nose-hover indication. Reward beside the find before any frustration or grabbing. Rehearse this ending separately from hidden placements and keep the container fixed throughout.','Finds and briefly indicates the visible container with comfortable component cues.','Reward discovery without the hover or rehearse the indication alone. Keep the task easy enough to avoid repeated prompting.'),
      ('Add a close return report','After an easy find and hover, offer your familiar hand target a step away. Reward the touch at your hand and release. Alternate rewards at the find with rewards after the return so indicating remains worthwhile. Keep yourself close enough that leaving the find is an easy choice.','Comfortably changes from the short indication to a one-step hand-touch report.','Bring your hand closer or reward at both locations. Do not withhold rewards to force a longer chain.',[['SCENTREPORT-1',3],['TOUCH-2',3]]),
      ('A tiny hidden search and report','Place the familiar secured container partly behind a broad safe object in the small known area. Say “report,” then support the known search, brief show and return touch with component cues. Reward generously, then finish. Gradually fade one extra prompt at a time without making the hiding harder.','Finds the easy container, briefly shows it and returns to touch with ordinary support across two sessions.','Reveal the container or return to the visible ending. This recreational chain does not certify an independent working alert.')],deps=[['ARTICLE-2',3],['SCENTINDICATE-2',3]],priority='Optional advanced')
    D['skills'][-1]['project']={'modules':[{'code':'ARTICLE'},{'code':'SCENTINDICATE'},{'code':'TOUCH'},{'code':'SCENTREPORT'}],'foundations':['SCENTMATCH']}
    new('ROUTINE','A short cooperative trick routine','Brainiacs','Combine three comfortable tricks with clear individual cues and a restful finish.','Showtime','An enclosed non-slip space, steady handler and generous curves. Choose only the dog’s comfortable versions; this optional routine requires no speed, music, audience or repeated performance.',[
      ('A bow and one open circle','Invite the familiar brief bow, reward and let the dog reset to stand. Then separately cue one broad circle around your still body and reward its finish. Practice each action alone between combinations. Keep full pauses so joining never turns into rapid twisting or repeated stretching.','Comfortably offers the two familiar actions with clear separate cues and an easy transition.','Do just one action or reward an ordinary stand between them. Skip any movement that looks stiff.'),
      ('Add a quiet final pose','After the familiar circle, let the dog settle their footing and invite the short comfortable photo pose without taking a picture. Reward and give the familiar finished cue. Rehearse the pose ending on its own before joining it. Keep the whole routine to a handful of gentle actions.','Completes bow, broad circle and brief pose with comfortable pauses and separate cues.','Remove the first action or shorten the pose. There is no need to perform all pieces every time.',[['ROUTINE-1',3],['POSE-2',3]]),
      ('One invitation, clear support','Say “showtime” before the familiar bow cue, then support circle and pose with their known cues. Reward between pieces whenever useful and finish with an honest break. On later occasions reduce only one prompt if the dog anticipates the sequence comfortably. One enjoyable supported routine is the full goal.','Enjoys the short three-action routine with clear cues and a restful ending on two occasions.','Keep individual cues and frequent rewards. Do not drill for an audience or interpret a missed cue as lost completion.')],deps=[['BOW-3',3],['CIRCLEME-2',3]],priority='Optional advanced')
    D['skills'][-1]['project']={'modules':[{'code':'BOW'},{'code':'CIRCLEME'},{'code':'POSE'},{'code':'ROUTINE'}],'foundations':[]}
    additions=[s for s in D['skills'] if s['code'] not in before]
    assert len(additions)==50, f'Expected 50 new skills, got {len(additions)}'
    for s in additions:
        if s['sheet']=='Care and equipment':s['sources']='A12; P11; R17; R18'
        if s['sheet']=='Scent adventures':s['sources']='A13; P32; P11; R01'
    next(s for s in additions if s['code']=='CRATE')['sources']+='; A11'
    heel=next(s for s in additions if s['code']=='HEEL')
    heel['steps'][0]['deps']=[]
    heel['steps'][3]['deps'].append(['FREE-2',3])
    next(s for s in additions if s['code']=='RHYTHM')['sources']+='; A14'
    next(s for s in additions if s['code']=='TRACKPERSON')['sources']+='; A15'
    return additions
